  const tb=btHTML({id:"wbs_ev",h:500,rowH:40,exportName:"earned-value-by-wbs",key:"id",facets:["lvl","pj"],rows:()=>rows,cols:[{k:"wbs",label:"WBS",fmt:r=>`<span class="num">${r.wbs}</span>`,val:r=>r.wbs},{k:"n",label:"WBS element",fmt:r=>`<span class="wl ${r.sum?"s":""}" style="--lv:${r.lv-1}">${r.ms?'<i class="msd"></i>':""}${esc(r.n)}</span>`,val:r=>r.n,wrap:1},{k:"pj",label:"Project",val:r=>r.pj},{k:"bac",label:"Budget (BAC)",fmt:r=>K$(r.bac),val:r=>r.bac},{k:"pv",label:"Planned value",fmt:r=>K$(r.pv),val:r=>r.pv},{k:"ev",label:"Earned value",fmt:r=>K$(r.ev),val:r=>r.ev},{k:"ac",label:"Actual cost",fmt:r=>K$(r.ac),val:r=>r.ac},{k:"sv",label:"Schedule variance",fmt:r=>`<span class="${r.sv<-.5?"bad-t":""}">${r.sv>0?"+":""}${r.sv.toFixed(1)}K</span>`,val:r=>r.sv},{k:"cv",label:"Cost variance",fmt:r=>`<span class="${r.cv<-.5?"bad-t":""}">${r.cv>0?"+":""}${r.cv.toFixed(1)}K</span>`,val:r=>r.cv},{k:"spi",label:"SPI",fmt:r=>pl(r.spi),val:r=>r.spi==null?-1:r.spi},{k:"cpi",label:"CPI",fmt:r=>pl(r.cpi),val:r=>r.cpi==null?-1:r.cpi},{k:"eac",label:"Forecast at completion",fmt:r=>K$(r.eac),val:r=>r.eac},{k:"vac",label:"Variance at completion",fmt:r=>(r.vac>0?"+":"")+r.vac.toFixed(1)+"K",val:r=>r.vac},{k:"lvl",label:"Level",val:r=>r.lvl}],open:id=>taskDrawer(id)});
